    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    patterns = []
    for r in {0, h - 1}:
        c = 0
        while c < w:
            if grid[r][c] == 0:
                c += 1
                continue
            seq = []
            while c < w and grid[r][c] != 0:
                seq.append(grid[r][c])
                c += 1
            patterns.append(seq)

    for r in range(1, h - 1):
        for c, color in enumerate(grid[r]):
            if color == 0:
                continue
            seq = next(seq for seq in patterns if color in seq)
            offset = seq.index(color)
            start = c - offset
            for i, value in enumerate(seq):
                x = start + i
                if 0 <= x < w:
                    out[r][x] = value
    return out
